def select_neighbor(archive: List[Tuple[np.ndarray, Tuple[float, float]]], instance: np.ndarray, distance_matrix_1: np.ndarray, distance_matrix_2: np.ndarray, distance_matrix_3: np.ndarray) -> np.ndarray:
    """
    Select a promising solution from the archive and generate a neighbor solution from it.

    Args:
    archive: List of (solution, objective) pairs. Each solution is a numpy array of node IDs.
             Each objective is a tuple of three float values.
    instance: Numpy array of shape (N, 4). Each row corresponds to a node and contains its coordinates in two 2D spaces: (x1, y1, x2, y2).
    distance_matrix_1: Distance matrix in the first objective space.
    distance_matrix_2: Distance matrix in the second objective space.
    distance_matrix_3: Distance matrix in the third objective space.

    Returns:
    A new neighbor solution (numpy array).
    """
    if not archive:
        raise ValueError("Archive is empty")

    def objective_balance(obj):
        return abs(obj[0] - obj[1]) + abs(obj[1] - obj[2]) + abs(obj[2] - obj[0])

    archive_sorted = sorted(archive, key=lambda x: objective_balance(x[1]))
    selected_idx = min(1, len(archive_sorted) - 1)
    base_solution = archive_sorted[selected_idx][0].copy()
    new_solution = base_solution.copy()
    n = len(new_solution)

    objectives = archive[selected_idx][1]
    worst_obj_idx = np.argmax(objectives)

    segment_length = max(3, min(7, n // 4))
    num_segments = n // segment_length

    segments = []
    for i in range(num_segments):
        start = i * segment_length
        end = start + segment_length
        segments.append(base_solution[start:end])

    other_indices = np.random.choice([i for i in range(len(archive)) if i != selected_idx], size=2, replace=False)
    sol1 = archive[other_indices[0]][0].copy()
    sol2 = archive[other_indices[1]][0].copy()

    for i in range(num_segments):
        if i % 2 == 0:
            segments[i] = sol1[i*segment_length:(i+1)*segment_length]
        else:
            segments[i] = sol2[i*segment_length:(i+1)*segment_length]

    new_solution = np.concatenate(segments)

    for _ in range(3):
        seg1 = np.random.randint(0, num_segments)
        seg2 = np.random.randint(0, num_segments)
        if seg1 != seg2:
            pos1 = np.random.randint(0, segment_length)
            pos2 = np.random.randint(0, segment_length)
            new_solution[seg1*segment_length+pos1], new_solution[seg2*segment_length+pos2] = new_solution[seg2*segment_length+pos2], new_solution[seg1*segment_length+pos1]

    if worst_obj_idx == 0:
        for i in range(n-1):
            if distance_matrix_1[new_solution[i], new_solution[i+1]] > distance_matrix_1[new_solution[i+1], new_solution[i]]:
                new_solution[i], new_solution[i+1] = new_solution[i+1], new_solution[i]
    elif worst_obj_idx == 1:
        for i in range(n-1):
            if distance_matrix_2[new_solution[i], new_solution[i+1]] > distance_matrix_2[new_solution[i+1], new_solution[i]]:
                new_solution[i], new_solution[i+1] = new_solution[i+1], new_solution[i]
    else:
        for i in range(n-1):
            if distance_matrix_3[new_solution[i], new_solution[i+1]] > distance_matrix_3[new_solution[i+1], new_solution[i]]:
                new_solution[i], new_solution[i+1] = new_solution[i+1], new_solution[i]

    if len(new_solution) != len(set(new_solution)):
        new_solution = base_solution.copy()

    return new_solution

